namespace TTSMixmaster.Core.Tts;

// Static legacy shapes; the player fixes global shadowing and the reserved repeat keyword.
internal static class TtsTemplates
{
    internal const string Player = """
-- {{COMMENT_NAME}} - Generated by TTSMixmaster
-- Music Player for Tabletop Simulator

local TtsMusicPlayer = {}

-- Playlist configuration
TtsMusicPlayer.playlist = {
    {{PLAYLIST}}
}

-- Player state
TtsMusicPlayer.currentTrack = 1  -- Lua is 1-indexed
TtsMusicPlayer.shuffle = false
TtsMusicPlayer["repeat"] = false
TtsMusicPlayer.isPlaying = false

-- Play current track
function TtsMusicPlayer.play()
    if #TtsMusicPlayer.playlist > 0 then
        local track = TtsMusicPlayer.playlist[TtsMusicPlayer.currentTrack]
        if track and track.url ~= "" then
            MusicPlayer.setPlaylist({{url = track.url, title = track.name}})
            MusicPlayer.setCurrentAudioclip({url = track.url, title = track.name})
            MusicPlayer.play()
            TtsMusicPlayer.isPlaying = true
            print("Now playing: " .. track.name)
        else
            print("No valid audio URL for current track")
        end
    else
        print("Playlist is empty")
    end
end

-- Stop playback
function TtsMusicPlayer.stop()
    MusicPlayer.pause()
    TtsMusicPlayer.isPlaying = false
    print("Music stopped")
end

-- Next track
function TtsMusicPlayer.next()
    if #TtsMusicPlayer.playlist > 0 then
        if TtsMusicPlayer.currentTrack < #TtsMusicPlayer.playlist then
            TtsMusicPlayer.currentTrack = TtsMusicPlayer.currentTrack + 1
        elseif TtsMusicPlayer["repeat"] then
            TtsMusicPlayer.currentTrack = 1
        end
        TtsMusicPlayer.play()
    end
end

-- Previous track
function TtsMusicPlayer.previous()
    if #TtsMusicPlayer.playlist > 0 then
        if TtsMusicPlayer.currentTrack > 1 then
            TtsMusicPlayer.currentTrack = TtsMusicPlayer.currentTrack - 1
        elseif TtsMusicPlayer["repeat"] then
            TtsMusicPlayer.currentTrack = #TtsMusicPlayer.playlist
        end
        TtsMusicPlayer.play()
    end
end

-- Set track by index
function TtsMusicPlayer.setTrack(index)
    if index >= 1 and index <= #TtsMusicPlayer.playlist then
        TtsMusicPlayer.currentTrack = index
        TtsMusicPlayer.play()
    else
        print("Track index out of range: " .. index)
    end
end

-- Get current track info
function TtsMusicPlayer.getCurrentTrack()
    if #TtsMusicPlayer.playlist > 0 then
        local track = TtsMusicPlayer.playlist[TtsMusicPlayer.currentTrack]
        if track then
            return track.name, TtsMusicPlayer.currentTrack
        end
    end
    return "No track", 0
end

-- Toggle shuffle
function TtsMusicPlayer.toggleShuffle()
    TtsMusicPlayer.shuffle = not TtsMusicPlayer.shuffle
    print("Shuffle: " .. (TtsMusicPlayer.shuffle and "ON" or "OFF"))
end

-- Toggle repeat
function TtsMusicPlayer.toggleRepeat()
    TtsMusicPlayer["repeat"] = not TtsMusicPlayer["repeat"]
    print("Repeat: " .. (TtsMusicPlayer["repeat"] and "ON" or "OFF"))
end

-- List all tracks
function TtsMusicPlayer.listTracks()
    print("=== " .. "{{NAME}}" .. " ===")
    for i, track in ipairs(TtsMusicPlayer.playlist) do
        local marker = (i == TtsMusicPlayer.currentTrack) and "► " or "  "
        print(marker .. i .. ". " .. track.name)
    end
end

-- Initialize on load
function onLoad()
    print("{{NAME}} loaded with " .. #TtsMusicPlayer.playlist .. " tracks")
    print("Use TtsMusicPlayer.play() to start playback")
    print("Use TtsMusicPlayer.listTracks() to see all tracks")
end

-- Export the music player
return TtsMusicPlayer
""";
